package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A zero value is not usable; construct with NewLimiter.
type Limiter struct {
	mu        sync.Mutex
	rate      float64   // tokens per second
	burst     float64   // bucket capacity
	tokens    float64   // current tokens
	last      time.Time // last refill time
	clock     Clock
}

// NewLimiter creates a limiter that refills rate tokens per second,
// with a maximum capacity of burst tokens.
func NewLimiter(rate float64, burst int) (*Limiter, error) {
	return NewLimiterWithClock(rate, burst, realClock{})
}

// NewLimiterWithClock is like NewLimiter with an injectable clock.
func NewLimiterWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 {
		return nil, fmt.Errorf("ratelimit: rate must be > 0, got %v", rate)
	}
	if burst <= 0 {
		return nil, fmt.Errorf("ratelimit: burst must be > 0, got %d", burst)
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst), // start full
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// advance refills tokens based on elapsed time. Caller must hold mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the number of tokens currently available (approximate,
// as of the current clock reading).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
